{"implementation":"def solve(case):
    threshold = case['threshold']
    accepted_call_ids = []
    diagnostics = []
    for call in case['calls']:
        gain = call['loss_without_call'] - call['loss_with_call']
        tokens = call['prediction_tokens']
        if tokens == 0:
            normalized_gain = 0.0
        else:
            normalized_gain = gain / tokens
        accepted = call.get('parseable', True) and normalized_gain >= threshold
        diagnostics.append({
            'call_id': call['call_id'],
            'accepted': accepted,
            'normalized_gain': normalized_gain
        })
        if accepted:
            accepted_call_ids.append(call['call_id'])
    return {'accepted_call_ids': accepted_call_ids, 'diagnostics': diagnostics}"}
